const catalog = require('./columns.json');
const escape = value =>
  String(typeof value === 'object' ? JSON.stringify(value) : value)
    .replace(/\|/g, '&#124;')
    .replace(/\n/g, ' ');
function dictionaryMarkdown() {
  const lines = [
    '# Measurement column dictionary',
    '',
    'Generated by `npm run measurements:docs` from `scripts/measurements/columns.json`. Do not edit this generated file.',
    '',
    'Read [the measurement guide](https://github.com/HailemariamMersha/capstone/blob/experiment/library-packet-probes/docs/measurements/guide.md) first. CSV cells are text on disk; the datatypes below describe their intended interpretation. Blank means missing/not applicable, never numeric zero. JSON can distinguish absent, null and empty string where CSV cannot. Import nanosecond decimal strings as text; spreadsheet numeric conversion loses precision.',
    '',
    catalog.notation,
    '',
    'Sources are read at collection time. No library version or missing observation is inferred from the current installation. Context on samples belongs to the parent attempt. Examples are sanitized illustrations, not additional observations.',
    '',
  ];
  for (const [name, file] of Object.entries(catalog.files)) {
    lines.push(
      `## ${name} (${file.columns.length} columns)`,
      '',
      file.row,
      '',
      '| Column | Meaning / applicability | Datatype; units | Source / calculation | Example | Blank |',
      '| --- | --- | --- | --- | --- | --- |',
    );
    for (const key of file.columns) {
      const f = { ...catalog.fields[key], ...file.overrides?.[key] };
      lines.push(
        `| \`${key}\` | ${escape(f.meaning)} Rows: ${escape(
          f.applicableRows,
        )} | ${escape(f.datatype)}; ${escape(f.units)} | ${escape(
          f.source,
        )}. ${escape(f.calculation)} | ${escape(f.example)} | ${escape(
          f.blank,
        )} |`,
      );
    }
    lines.push('');
  }
  return lines.join('\n');
}
module.exports = { catalog, dictionaryMarkdown };
if (require.main === module) {
  const fs = require('node:fs');
  const path = require('node:path');
  const destination = path.resolve(
    __dirname,
    '../../docs/measurements/columns.md',
  );
  const content = dictionaryMarkdown();
  if (process.argv.includes('--check')) {
    if (
      !fs.existsSync(destination) ||
      fs.readFileSync(destination, 'utf8') !== content
    ) {
      console.error(
        'Column documentation is stale; run npm run measurements:docs.',
      );
      process.exitCode = 1;
    }
  } else fs.writeFileSync(destination, content);
}
